select 
from batch.job_dependency_waiting_launch
where tenant_id = #{tenantId} and request_id = #{requestId}

select count(*)
from batch.job_dependency_waiting_launch w
join batch.job_definition job
  on job.tenant_id = w.tenant_id
 and job.job_code = w.job_code
where w.tenant_id = #{tenantId}
  and job.calendar_code = #{calendarCode}
  and w.biz_date = #{bizDate}
  and w.wait_status = 'WAITING'

mapper.update:
update batch.job_dependency_waiting_launch
set wait_status = #{targetStatus},
    released_at = CASE WHEN #{targetStatus} = 'RELEASED' THEN CURRENT_TIMESTAMP ELSE released_at END,
    updated_at = CURRENT_TIMESTAMP
where tenant_id = #{tenantId} and request_id = #{requestId}
  and wait_status = #{expectedStatus}
